#[allow(unused_variables)] fn one_for_each_0_bits(q: &dyn Query, asker: &Asker, id: ObjectId) -> u32 { let mut bits = 0u32; if q.chars(id).is(CardType::Artifact) { bits |= 1 << 0; } if q.chars(id).is(CardType::Battle) { bits |= 1 << 1; } if q.chars(id).is(CardType::Creature) { bits |= 1 << 2; } if q.chars(id).is(CardType::Enchantment) { bits |= 1 << 3; } if q.chars(id).is(CardType::Instant) { bits |= 1 << 4; } if q.chars(id).is(CardType::Kindred) { bits |= 1 << 5; } if q.chars(id).is(CardType::Land) { bits |= 1 << 6; } if q.chars(id).is(CardType::Planeswalker) { bits |= 1 << 7; } if q.chars(id).is(CardType::Sorcery) { bits |= 1 << 8; } bits }
fn one_for_each_0_fits(q: &dyn Query, choice: &Choice, set: &[ObjectId]) -> bool { let asker = &Asker::new(choice.source, choice.chooser); let mut used = vec![0u32]; for &id in set { let bits = one_for_each_0_bits(q, asker, id); let mut next: Vec<u32> = Vec::new(); for &taken in &used { for each in 0..9 { let one = 1u32 << each; if bits & one != 0 && taken & one == 0 && !next.contains(&(taken | one)) { next.push(taken | one); } } } used = next; } !used.is_empty() }
fn one_for_each_0(q: &dyn Query, choice: &Choice, _: u32) -> Verdict { Verdict { complete: one_for_each_0_fits(q, choice, choice.selected), addable: Bits::of(choice.candidates.len(), |i| { let mut set = choice.selected.to_vec(); set.push(choice.candidates[i]); one_for_each_0_fits(q, choice, &set) }) } }
fn largest_one_for_each_0(q: &dyn Query, choice: &Choice, _: u32) -> Vec<ObjectId> { let mut kept: Vec<ObjectId> = Vec::new(); for &id in choice.candidates { kept.push(id); if !one_for_each_0_fits(q, choice, &kept) { kept.pop(); } } kept }
